export class CustomVideoDecoder{static supports(e,s){return!1}}export class CustomAudioDecoder{static supports(e,s){return!1}}export class CustomVideoEncoder{static supports(e,s){return!1}}export class CustomAudioEncoder{static supports(e,s){return!1}}export const customVideoDecoders=[],customAudioDecoders=[],customVideoEncoders=[],customAudioEncoders=[],registerDecoder=o=>{if(o.prototype instanceof CustomVideoDecoder){const e=o;if(customVideoDecoders.includes(e)){console.warn("Video decoder already registered.");return}customVideoDecoders.push(e)}else if(o.prototype instanceof CustomAudioDecoder){const e=o;if(customAudioDecoders.includes(e)){console.warn("Audio decoder already registered.");return}customAudioDecoders.push(e)}else throw new TypeError("Decoder must be a CustomVideoDecoder or CustomAudioDecoder.")},registerEncoder=o=>{if(o.prototype instanceof CustomVideoEncoder){const e=o;if(customVideoEncoders.includes(e)){console.warn("Video encoder already registered.");return}customVideoEncoders.push(e)}else if(o.prototype instanceof CustomAudioEncoder){const e=o;if(customAudioEncoders.includes(e)){console.warn("Audio encoder already registered.");return}customAudioEncoders.push(e)}else throw new TypeError("Encoder must be a CustomVideoEncoder or CustomAudioEncoder.")};
